effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     vec2 randVec(float inVal){

         return vec2(fract(sin(dot(vec2(inVal*1.1,2352.75053) ,vec2(12.9898,78.233))) * 43758.5453)-0.5,
                     fract(sin(dot(vec2(715.23515, inVal) ,vec2(27.2311,31.651))) * 65161.6513)-0.5);

     }

     float randFloat(vec2 inVal){
         return fract(sin(dot(vec2(inVal.x, inVal.y) ,vec2(89.4516,35.516))) * 13554.3651);

     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = acTime;

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((0.0+angle)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0-position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         float zoom = autop? sin(PROGRESS + (iTime*0.5)) : sin(PROGRESS*0.1);
         zoom = 0.9+pow(((iMouse.x+iMouse.y)/iResolution.x)*1.,3.0); 

         float sharpness = sharpnessx*zoom; // maybe plug in ddx and ddy here to mimic mip-mapping (avoid artifacts at long distances)
         // float expansionSpeed = 4.0;
         // float rainSpeed = 0.6;
         // float numRings = 3.0;
         // const float numIterations = 4.0;
         // float strength = 0.3;

         // other numbers:
         const float pi = 3.141592;
         float newTime = autop? PROGRESS + (iTime*rainSpeed) : PROGRESS*rainSpeed;

         vec2 uv;
         vec2 uvStep;
         fragColor = vec4(0.);
         for(float iterations = 0.; iterations < numIterations; iterations++){
             for(float xpos = -1.;xpos<=1.;xpos++){
                 for(float ypos = -1.;ypos<=1.;ypos++){
                     uv = TanRyu;
                     // uv = (2.*fragCoord.xy - iResolution.xy) / iResolution.y;
                     uv /= zoom;
                     uv += iterations*vec2(3.21,2.561);
                     uv += vec2(xpos*0.3333,ypos*0.3333);
                     uvStep = (ceil((uv*1.0-vec2(.5,.5)))/1.);
                     uvStep += vec2(xpos,ypos)*100.;
                     uv = vec2(fract(uv.x+0.5)-.5,fract(uv.y+0.5)-.5);

                     // Variables:
                     float timeRand = randFloat(uvStep);
                     float timeLoop = fract(newTime+timeRand);
                     float timeIter = floor(newTime+timeRand);


                     /// Creating ringMap:
                     float ringMap = sharpness*9.*distance(uv, randVec(timeIter+uvStep.x+uvStep.y)*0.5);
                     //float ringMap = sharpness*9.*distance(uv, randVec(0.)*0.);
                     float clampMinimum = -(1.+((numRings-1.)*2.0));
                     ringMap = clamp((ringMap-expansionSpeed*sharpness*(timeLoop))+1., clampMinimum, 1.);

                     // Rings and result
                     float rings = (cos((ringMap+newTime)*pi)+1.0)/2.;
                     rings *= pow(1.-timeLoop,2.);
                     float bigRing = sin((ringMap-clampMinimum)/(1.-clampMinimum)*pi);
                     float result = rings * bigRing;
                     fragColor += vec4(result)*strength;
                 }
             }
         }

 	vec4 factor = mix(texColorX,fragColor,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
         // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
